/* GW Suivi — PWA autonome, aucune dépendance externe. */
const $ = (s, root = document) => root.querySelector(s);
const config = window.GW_CONFIG || {};
const CLOUD = Boolean(config.cloudflareApi === true);
const ROOT = document.querySelector('#app');
const LS_SESSION = 'gw-suivi-session-v2';
const PHONE_EXAMPLE = '+22890123456';
const DB_NAME = 'gw-suivi-v2-cloudflare';
const icons = {dashboard:'▦',tasks:'☷',employees:'♙',settings:'⚙',calendar:'◷',money:'◆',clock:'◴',check:'✓',alert:'!',add:'+',sync:'↻',logout:'⇥'};
const labels = {todo:'À faire',in_progress:'En cours',submitted:'À valider',approved:'Validée',changes_requested:'À corriger'};
const today = () => new Date();
const iso = () => new Date().toISOString();
const uuid = () => (crypto.randomUUID ? crypto.randomUUID() : `gw-${Date.now()}-${Math.random().toString(16).slice(2)}`);
const esc = value => String(value ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money = n => `${new Intl.NumberFormat('fr-FR').format(Number(n || 0))} F`;
const dateFmt = (value, noTime = false) => !value ? 'Non définie' : new Intl.DateTimeFormat('fr-FR', {day:'2-digit',month:'short',...(noTime?{}:{hour:'2-digit',minute:'2-digit'})}).format(new Date(value));
const inHours = (h) => new Date(Date.now()+3600000*h).toISOString();
const inputDate = value => {if(!value)return '';const d = new Date(value);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;};
const initials = s => String(s||'GW').trim().split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase();
const statusClass = s => labels[s] ? s : 'todo';
function dueLabel(task){if(task.status==='approved')return 'Terminée';const diff = new Date(task.due_at).getTime()-Date.now();if(diff<0)return 'En retard';if(diff<86400000)return 'Dans moins de 24 h';return dateFmt(task.due_at);}
function dueClass(task){if(task.status==='approved')return '';const diff=new Date(task.due_at).getTime()-Date.now();return diff<0?'critical':diff<86400000?'warning':'';}
function isEligible(task){return Number(task.bonus_amount)>0 && task.submitted_at && task.bonus_before && new Date(task.submitted_at).getTime()<=new Date(task.bonus_before).getTime();}
const app = {view:'dashboard',tab:'all',query:'',modal:null,mode:CLOUD?'cloud':'demo',session:null,meId:null,people:[],tasks:[],queue:[],lastSync:null,syncing:false,online:navigator.onLine,authView:'login',authError:'',installed:false,ready:false,toast:null,superData:null,inviteCode:null};

/* IndexedDB garde les instantanés et les opérations en attente après fermeture. */
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(new Error('IndexedDB indisponible'));return;}const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('snapshots'))req.result.createObjectStore('snapshots');};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function storageGet(key){try{const db=await openDB();return await new Promise((resolve,reject)=>{const req=db.transaction('snapshots','readonly').objectStore('snapshots').get(key);req.onsuccess=()=>{db.close();resolve(req.result ?? null)};req.onerror=()=>{db.close();reject(req.error)}})}catch{try{return JSON.parse(localStorage.getItem('gw-fallback-'+key)||'null')}catch{return null}}}
async function storagePut(key,value){try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction('snapshots','readwrite');tx.objectStore('snapshots').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();}catch{try{localStorage.setItem('gw-fallback-'+key,JSON.stringify(value));}catch(e){notify('Stockage local insuffisant : exporte tes données.',true)}}}
async function storageDelete(key){try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction('snapshots','readwrite');tx.objectStore('snapshots').delete(key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close();}catch{}localStorage.removeItem('gw-fallback-'+key)}
const storageKey = ()=> CLOUD ? `cloud-${app.session?.user?.id || 'guest'}` : 'demo';
async function save(){await storagePut(storageKey(),{people:app.people,tasks:app.tasks,queue:app.queue,meId:app.meId,lastSync:app.lastSync});}
function restore(snapshot){app.people=snapshot?.people||[];app.tasks=snapshot?.tasks||[];app.queue=snapshot?.queue||[];app.meId=snapshot?.meId||null;app.lastSync=snapshot?.lastSync||null;}
function seed(){const id1=uuid(),id2=uuid(),id3=uuid(),id4=uuid();app.people=[{id:id1,name:'Administration GW',email:'admin@demo.local',role:'admin',active:true},{id:id2,name:'Amina K.',email:'amina@demo.local',role:'employee',active:true},{id:id3,name:'Kevin D.',email:'kevin@demo.local',role:'employee',active:true},{id:id4,name:'Sarah T.',email:'sarah@demo.local',role:'employee',active:true}];app.meId=id1;
  const mk=(title,desc,person,due,bonus,before,status='todo')=>({id:uuid(),title,description:desc,employee_id:person,priority:'normal',due_at:inHours(due),bonus_amount:bonus,bonus_before:inHours(before),status,submitted_at:null,approved_at:null,bonus_awarded:0,bonus_override:false,client_submitted_at:null,employee_note:'',admin_note:'',updated_at:iso(),created_at:iso()});
  app.tasks=[mk('Préparer le rapport des opérations','Récapitulatif des transactions et des montants de la semaine.',id2,50,5000,24,'in_progress'),mk('Contacter les clients prioritaires','Faire le suivi des demandes en attente et préparer un compte rendu.',id3,18,3000,12),mk('Vérifier les paiements en attente','Comparer les confirmations de paiement avec les dossiers clients.',id4,36,4000,24),mk('Organiser les documents du mois','Classer les justificatifs et signaler les dossiers incomplets.',id2,96,2000,72)];}
function me(){return app.people.find(p=>p.id===app.meId)||null}
function admin(){return me()?.role==='admin'}
function superAdmin(){return CLOUD&&me()?.role==='superadmin'}
function person(id){return app.people.find(p=>p.id===id)}
function normalizedContactPhone(value){let v=String(value||'').replace(/[\s.()\-]/g,'');if(!v)return '';if(v.startsWith('00'))v='+'+v.slice(2);if(/^\d{8}$/.test(v))v='+228'+v;else if(/^\d{11,15}$/.test(v))v='+'+v;if(!/^\+[1-9]\d{7,14}$/.test(v))throw new Error('Numéro invalide : utilise +228XXXXXXXX (ou un autre indicatif).');return v;}
function checkedContacts(email,phone){email=String(email||'').trim().toLowerCase();phone=normalizedContactPhone(phone);if(!email&&!phone)throw new Error('Indique une adresse e-mail ou un numéro WhatsApp au minimum.');if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Adresse e-mail invalide.');return {email,phone};}
function contactLabel(p){return [p.email,p.phone].filter(Boolean).join(' · ')||'Sans coordonnées';}
function inviteMessage(inv){return `Bonjour ${inv.name},\n\nVoici ton accès personnel à GW Suivi (${inv.role==='admin'?'Responsable':'Employé'}).\nOuvre ce lien pour définir ton mot de passe :\n${inv.link}\n\nCe lien est valable 7 jours et ne doit pas être partagé.`;}
function inviteCard(inv){if(!inv)return '';return `<div class="invite-card"><strong>Lien d’activation de ${esc(inv.name)}</strong><p>À transmettre directement. Le lien expire dans 7 jours et ne pourra être utilisé qu’une fois.</p><div class="invite-link">${esc(inv.link)}</div><div class="button-row invite-actions">${inv.phone?'<button type="button" class="btn primary" data-action="share-whatsapp">◉ Envoyer via WhatsApp</button>':''}${inv.email?'<button type="button" class="btn navy" data-action="share-email">✉ Envoyer par e-mail</button>':''}<button type="button" class="btn ghost" data-action="share-copy">Copier le lien</button></div><small>WhatsApp ou la messagerie s’ouvrira avec le message préparé. Confirme son envoi dans l’application.</small></div>`;}
function shareInvite(channel){const inv=app.inviteResult;if(!inv||!inv.link)throw new Error('Crée d’abord un lien d’activation.');const message=inviteMessage(inv);if(channel==='whatsapp'){if(!inv.phone)throw new Error('Aucun numéro WhatsApp renseigné.');const target='https://wa.me/'+inv.phone.replace(/\D/g,'')+'?text='+encodeURIComponent(message);const tab=window.open(target,'_blank');if(tab){try{tab.opener=null;}catch{}}else window.location.href=target;notify('WhatsApp ouvert : confirme l’envoi du message.');return;}if(channel==='email'){if(!inv.email)throw new Error('Aucune adresse e-mail renseignée.');window.location.href='mailto:'+encodeURIComponent(inv.email)+'?subject='+encodeURIComponent('Ton accès à GW Suivi')+'&body='+encodeURIComponent(message);notify('Messagerie ouverte : confirme l’envoi.');return;}if(channel==='copy'){navigator.clipboard.writeText(inv.link).then(()=>notify('Lien copié.')).catch(()=>notify('La copie a échoué : sélectionne le lien affiché.',true));}}

function visibleTasks(){return admin()?app.tasks:app.tasks.filter(t=>t.employee_id===app.meId)}
function visiblePeople(){return admin()?app.people:app.people.filter(p=>p.id===app.meId)}
function countFor(id){return app.tasks.filter(t=>t.employee_id===id && t.status!=='approved').length}
function notify(message,isError=false){const el=document.createElement('div');el.className=`toast${isError?' error':''}`;el.textContent=message;let wrap=$('.toast-wrap');if(!wrap){wrap=document.createElement('div');wrap.className='toast-wrap';document.body.append(wrap);}wrap.append(el);setTimeout(()=>el.remove(),4200);}
async function persistAndRender(){await save();render();}
function setView(view){if(view==='employees'&&!admin())return;if(superAdmin()&&!['super','admins','errors','settings'].includes(view))return;if(!superAdmin()&&['super','admins','errors'].includes(view))return;app.view=view;app.tab='all';app.query='';render();window.scrollTo({top:0,behavior:'instant'});}
function navItems(){if(superAdmin())return [{id:'super',name:'Supervision',icon:'◈'},{id:'admins',name:'Responsables',icon:'♙'},{id:'errors',name:'Erreurs et événements',icon:'⚑'},{id:'settings',name:'Paramètres',icon:icons.settings}];return [{id:'dashboard',name:'Tableau de bord',icon:icons.dashboard},{id:'tasks',name:'Mes tâches',icon:icons.tasks},...(admin()?[{id:'employees',name:'Employés',icon:icons.employees}]:[]),{id:'settings',name:'Paramètres',icon:icons.settings}];}
function navHTML(mobile=false){return navItems().map(item=>mobile?`<button data-action="view" data-id="${item.id}" class="${app.view===item.id?'active':''}"><span>${item.icon}</span>${esc(item.name.replace('Tableau de bord','Accueil').replace('Paramètres','Réglages'))}</button>`:`<button class="nav-btn ${app.view===item.id?'active':''}" data-action="view" data-id="${item.id}"><span class="ico">${item.icon}</span>${esc(item.name)}</button>`).join('');}
function badge(task){return `<span class="status ${statusClass(task.status)}">${esc(labels[task.status]||task.status)}</span>`}
function headerText(){return {dashboard:['Vue d’ensemble', 'Bienvenue sur ton espace de travail'],tasks:[admin()?'Gestion des tâches':'Mes missions','Organise, suis et accomplis tes objectifs'],employees:['Équipe Greatness Winner','Gérer les membres et leurs responsabilités'],super:['Centre de supervision','Santé de la plateforme et accès'],admins:['Administrateurs','Gérer les responsables de Greatness Winner'],errors:['Journal technique','Incidents et actions récentes'],settings:['Paramètres','Informations, sauvegardes et connexion']}[app.view]||['GW Suivi',''];}
function shell(content){const [title,sub]=headerText();const syncText=!app.online?'Hors connexion':app.syncing?'Synchronisation…':app.queue.length?`${app.queue.length} en attente`:CLOUD?'Synchronisé':'Mode local';const syncClass=!app.online?'offline':app.queue.length?'pending':'';return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-icon">GW</span><div class="brand-copy"><strong>GW Suivi</strong><span>Greatness Winner</span></div></div><div class="nav-title">MENU PRINCIPAL</div><nav>${navHTML()}</nav><div class="sidebar-bottom"><div class="userline"><div class="avatar navy">${esc(initials(me()?.name))}</div><div><strong>${esc(me()?.name||'Utilisateur')}</strong><small>${superAdmin()?'Super administrateur':admin()?'Administrateur':'Employé'}</small></div></div></div></aside><main class="main-area"><header class="topbar"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="top-actions"><span title="${app.lastSync?`Dernière synchronisation : ${dateFmt(app.lastSync)}`:'Aucune synchronisation cloud'}" class="sync-pill ${syncClass}"><span class="dot"></span>${esc(syncText)}</span><button class="icon-btn" data-action="sync" title="Actualiser les données">${icons.sync}</button></div></header><div class="content">${content}</div></main></div><nav class="mobile-nav">${navHTML(true)}</nav>${app.modal?modalHTML():''}`;}
function statCard(label,value,sub,icon,tone=''){return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${esc(label)}</span><span class="stat-icon ${tone}">${icon}</span></div><strong>${esc(value)}</strong><small>${esc(sub)}</small></article>`;}
function dashboard(){const tasks=visibleTasks();const pending=tasks.filter(t=>t.status==='submitted').length;const open=tasks.filter(t=>t.status!=='approved').length;const earned=tasks.reduce((s,t)=>s+Number(t.bonus_awarded||0),0);const soon=tasks.filter(t=>t.status!=='approved' && (new Date(t.due_at)-Date.now())<86400000).length;
  const top=`<div class="hero"><div><h2>Bonjour, ${esc(me()?.name?.split(' ')[0]||'équipe')} 👋</h2><p>${admin()?'Pilote les missions de ton équipe, suis les échéances et valorise le travail bien fait.':'Retrouve tes priorités, avance sur tes missions et décroche tes primes de performance.'}</p></div><div class="hero-icon">✦</div></div>`;
  const stats=`<div class="stats">${statCard(admin()?'Tâches actives':'Mes missions',open,'À suivre',icons.tasks)}${statCard(admin()?'En attente':'À soumettre',admin()?pending:tasks.filter(t=>t.status==='todo'||t.status==='in_progress'||t.status==='changes_requested').length,admin()?'À valider':'Travaux en cours',icons.clock,'orange')}${statCard('Échéances proches',soon,'Dans les 24 h ou en retard',icons.alert,'red')}${statCard('Primes accordées',money(earned),'Après validation',icons.money,'green')}</div>`;
  const recent=[...tasks].sort((a,b)=>new Date(a.due_at)-new Date(b.due_at)).slice(0,5);
  const taskPanel=`<section class="panel"><div class="panel-head"><div><h3>${admin()?'Tâches prioritaires':'Mes prochaines tâches'}</h3><p>Les échéances les plus proches</p></div><button data-action="view" data-id="tasks">Tout voir →</button></div><div class="task-list">${recent.length?recent.map(t=>`<div class="task-row"><div class="task-dot">${t.status==='approved'?'✓':'▤'}</div><div class="task-info"><div class="task-name">${esc(t.title)}</div><div class="task-meta">${admin()?esc(person(t.employee_id)?.name||'Non attribuée')+' · ':''}${esc(dueLabel(t))}</div></div><div class="task-end">${badge(t)}${Number(t.bonus_amount)>0?`<span class="task-money">+ ${money(t.bonus_amount)}</span>`:''}</div></div>`).join(''):empty('Aucune tâche','Ajoute une première mission pour démarrer.')}</div></section>`;
  const items=admin()?app.people.filter(p=>p.role!=='admin').map(p=>({title:p.name,desc:`${countFor(p.id)} tâche(s) en cours`,icon:'♙'})).slice(0,4):tasks.filter(t=>Number(t.bonus_amount)>0).slice(0,4).map(t=>({title:t.title,desc:`Prime potentielle de ${money(t.bonus_amount)} avant le ${dateFmt(t.bonus_before)}`,icon:'◆'}));
  const sidePanel=`<section class="panel"><div class="panel-head"><div><h3>${admin()?'L’équipe':'Opportunités de prime'}</h3><p>${admin()?'Membres et missions en cours':'Les primes associées aux tâches'}</p></div>${admin()?'<button data-action="view" data-id="employees">Voir →</button>':''}</div><div class="activity-list">${items.length?items.map(e=>`<div class="activity-item"><span class="activity-icon">${e.icon}</span><div><strong>${esc(e.title)}</strong><p>${esc(e.desc)}</p></div></div>`).join(''):empty('Aucun élément','Les informations s’afficheront ici.')}</div></section>`;
  return `${top}${(!app.online&&CLOUD)?'<div class="notice">Mode hors ligne : les dernières données conservées sur cet appareil restent accessibles. Les modifications seront envoyées au retour d’Internet.</div>':''}${stats}<div class="panel-grid">${taskPanel}${sidePanel}</div>`;
}
function empty(title,subtitle){return `<div class="empty"><span class="big">◌</span><strong>${esc(title)}</strong>${esc(subtitle)}</div>`}
function tasksView(){const tasks=visibleTasks().filter(t=>app.tab==='all'||t.status===app.tab).filter(t=>`${t.title} ${t.description} ${person(t.employee_id)?.name||''}`.toLowerCase().includes(app.query.toLowerCase())).sort((a,b)=>new Date(a.due_at)-new Date(b.due_at));
 const tabs=[['all','Toutes'],['todo','À faire'],['in_progress','En cours'],['submitted','À valider'],['approved','Terminées']];
 return `<div class="page-heading"><div><h2>${admin()?'Toutes les missions':'Mes tâches assignées'}</h2><p>${visibleTasks().length} tâche(s) ${admin()?'dans l’équipe':'sur ton compte'}</p></div>${admin()?'<button class="btn primary" data-action="new-task">+ Nouvelle tâche</button>':''}</div><div class="toolbar"><label class="search"><span>⌕</span><input id="search-tasks" type="search" placeholder="Rechercher une tâche…" value="${esc(app.query)}" /></label><div class="filter-row">${tabs.map(([id,name])=>`<button class="filter ${app.tab===id?'active':''}" data-action="tab" data-id="${id}">${name}</button>`).join('')}</div></div><div class="board">${tasks.length?tasks.map(taskCard).join(''):empty('Aucune tâche trouvée','Modifie les filtres ou crée une nouvelle mission.')}</div>`;
}
function taskCard(t){const actions=[];if(admin()){if(t.status==='submitted'){actions.push(`<button class="btn tiny navy" data-action="approve" data-id="${t.id}">✓ Valider</button><button class="btn tiny danger" data-action="reject" data-id="${t.id}">Demander correction</button>`);}actions.push(`<button class="btn tiny ghost" data-action="edit-task" data-id="${t.id}">Modifier</button>`);}
 else if(t.status!=='approved'){if(t.status==='todo'||t.status==='changes_requested')actions.push(`<button class="btn tiny ghost" data-action="start" data-id="${t.id}">Commencer</button>`);if(t.status!=='submitted')actions.push(`<button class="btn tiny navy" data-action="submit" data-id="${t.id}">Soumettre le travail</button>`);}
 return `<article class="work-card"><div style="min-width:0;flex:1"><h3>${esc(t.title)}</h3><p>${esc(t.description||'Aucune description fournie.')}</p><div class="card-tags">${badge(t)}<span class="pill ${dueClass(t)}">${icons.clock} ${esc(dueLabel(t))}</span>${admin()?`<span class="pill">♙ ${esc(person(t.employee_id)?.name||'Employé inconnu')}</span>`:''}<span class="pill">${t.priority==='high'?'⚑ Urgent':t.priority==='low'?'Priorité basse':'Priorité normale'}</span>${t.bonus_awarded>0?`<span class="pill">✓ Prime accordée : ${money(t.bonus_awarded)}</span>`:Number(t.bonus_amount)>0?`<span class="pill">◆ Prime : ${money(t.bonus_amount)} si soumis avant le ${dateFmt(t.bonus_before)}</span>`:''}</div>${t.employee_note?`<p style="margin:11px 0 0;color:#476688">Compte rendu : ${esc(t.employee_note)}</p>`:''}${t.admin_note?`<p style="margin:8px 0 0;color:#bd6d4c">Retour admin : ${esc(t.admin_note)}</p>`:''}</div><div class="task-buttons"><span class="task-money">${Number(t.bonus_amount)>0?'+ '+money(t.bonus_amount):'Sans prime'}</span><div class="button-row">${actions.join('')}</div></div></article>`;
}
function employeesView(){if(!admin())return dashboard();const people=app.people.filter(p=>p.role==='employee');return `<div class="page-heading"><div><h2>Les collaborateurs</h2><p>${people.length} employé(s) enregistré(s)</p></div><button class="btn primary" data-action="new-person">+ Ajouter un employé</button></div><div class="people-grid">${people.map(p=>`<article class="people-card"><div class="person-top"><div class="avatar orange">${esc(initials(p.name))}</div><div><h3>${esc(p.name)}</h3><p>${esc(contactLabel(p))}</p></div></div><div class="people-stat"><span><strong>${countFor(p.id)}</strong> mission(s) actives</span><span>${p.user_id?'Compte activé':'Activation en attente'}</span></div><div class="button-row" style="margin-top:15px"><button class="btn light tiny" data-action="assign" data-id="${p.id}">+ Assigner</button>${CLOUD&&!p.user_id?`<button class="btn navy tiny" data-action="reinvite-employee" data-id="${esc(p.id)}">Envoyer l’accès</button>`:''}</div></article>`).join('')||empty('Pas encore d’employé','Ajoute un membre pour attribuer sa première mission.')}</div>${CLOUD?'<div class="notice blue" style="margin-top:20px">Les employés activent leur compte via un lien envoyé par WhatsApp ou e-mail. Un numéro ou une adresse suffit.</div>':''}`;}
function settingsView(){const last=app.lastSync?dateFmt(app.lastSync):'Aucune';return `<div class="page-heading"><div><h2>Mon application</h2><p>Stockage et préférences</p></div></div><div class="panel settings-card"><h3>Application installable & hors connexion</h3><p>GW Suivi garde un instantané des données et les modifications effectuées sur cet appareil. ${CLOUD?'Les changements non synchronisés sont envoyés lorsque la connexion revient.':'Ce mode démonstration est local : les modifications ne sont pas partagées entre appareils.'}</p><div class="settings-row"><div><strong>Mode d’utilisation</strong><span>${CLOUD?'Cloud sécurisé + cache local':'Démonstration locale'}</span></div><span class="pill">${app.online?'Connexion détectée':'Sans connexion'}</span></div><div class="settings-row"><div><strong>Dernière synchronisation</strong><span>${esc(last)} · ${app.queue.length} modification(s) en attente</span></div><button class="btn ghost tiny" data-action="sync">↻ Actualiser</button></div><div class="settings-row"><div><strong>Sauvegarde locale</strong><span>Exporter une copie JSON des données affichées</span></div><button class="btn ghost tiny" data-action="export">↓ Exporter</button></div>${!CLOUD?`<div class="settings-row"><div><strong>Restaurer une sauvegarde</strong><span>Importe un fichier JSON GW Suivi sur cet appareil</span></div><button class="btn ghost tiny" data-action="import">↑ Importer</button></div><div class="settings-row"><div><strong>Tester le compte d’un employé</strong><span>Changement de rôle disponible uniquement dans la démonstration</span></div><select id="demo-role" style="max-width:195px;padding:9px;border-radius:9px;border:1px solid var(--border)">${app.people.map(p=>`<option value="${p.id}" ${p.id===app.meId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div>`:''}<div class="settings-row"><div><strong>Installer GW Suivi</strong><span>Depuis le menu du navigateur : « Ajouter à l’écran d’accueil »</span></div><button class="btn ghost tiny" data-action="install">Installer</button></div>${CLOUD?`<div class="settings-row"><div><strong>Compte sécurisé</strong><span>Déconnecte-toi et efface le cache local de ce compte</span></div><button class="btn danger tiny" data-action="logout">Se déconnecter</button></div>`:''}</div><div class="notice blue" style="margin-top:18px">Les données locales restent sur cet appareil, mais peuvent être supprimées si tu effaces les données du navigateur ou désinstalles l’application. Pense à exporter une sauvegarde. Sur un appareil partagé, évite de laisser une session ouverte.</div><input type="file" accept="application/json,.json" id="import-file" class="hidden" />`;}
function modalHTML(){if(!app.modal)return '';const type=app.modal.type;let title='',body='';if(type==='task'){const t=app.modal.task||{};title=t.id?'Modifier une tâche':'Attribuer une tâche';const choices=app.people.filter(p=>p.active&&p.role==='employee');body=`<form id="task-form"><div class="form-grid"><div class="field full"><label for="title">Intitulé de la mission *</label><input id="title" name="title" maxlength="130" required value="${esc(t.title||'')}" placeholder="Ex. Préparer le bilan journalier" /></div><div class="field full"><label for="description">Instructions</label><textarea id="description" name="description" maxlength="3000" placeholder="Décris le travail attendu…">${esc(t.description||'')}</textarea></div><div class="field full"><label for="employee_id">Attribuer à *</label><select id="employee_id" name="employee_id" required>${choices.length?choices.map(p=>`<option value="${p.id}" ${p.id===(t.employee_id||app.modal.employeeId)?'selected':''}>${esc(p.name)}</option>`).join(''):'<option value="">Ajoute d’abord un employé</option>'}</select></div><div class="field"><label for="due_at">Date limite *</label><input type="datetime-local" id="due_at" name="due_at" required value="${esc(inputDate(t.due_at||inHours(48)))}" /></div><div class="field"><label for="priority">Priorité</label><select id="priority" name="priority"><option value="normal" ${t.priority==='normal'||!t.priority?'selected':''}>Normale</option><option value="high" ${t.priority==='high'?'selected':''}>Urgente</option><option value="low" ${t.priority==='low'?'selected':''}>Basse</option></select></div><div class="field"><label for="bonus_amount">Prime de performance (FCFA)</label><input type="number" id="bonus_amount" name="bonus_amount" min="0" max="100000000" step="100" value="${Number(t.bonus_amount||0)}" /></div><div class="field"><label for="bonus_before">À soumettre avant le (pour la prime)</label><input type="datetime-local" id="bonus_before" name="bonus_before" value="${esc(inputDate(t.bonus_before||inHours(24)))}" /></div><div class="field full"><div class="form-help">La prime est accordée uniquement si le travail a été soumis avant l'heure fixée ET validé par l'administrateur. Elle n'est pas un paiement automatique.</div></div></div><div class="form-foot"><button class="btn ghost" type="button" data-action="close-modal">Annuler</button><button class="btn primary" type="submit" ${choices.length?'':'disabled'}>${t.id?'Enregistrer':'Créer la mission'}</button></div></form>`;}
 if(type==='person'){title='Ajouter un employé';body=`<form id="person-form"><p class="modal-desc">Renseigne son nom, puis au moins une coordonnée pour envoyer son accès.</p><div class="form-grid"><div class="field full"><label for="person_name">Nom complet *</label><input id="person_name" name="person_name" required maxlength="100" placeholder="Prénom et nom" /></div><div class="field"><label for="person_email">E-mail (facultatif)</label><input type="email" id="person_email" name="person_email" maxlength="250" placeholder="nom@entreprise.com" /></div><div class="field"><label for="person_phone">WhatsApp (facultatif)</label><input type="tel" id="person_phone" name="person_phone" inputmode="tel" placeholder="+22890123456" /></div><p class="help-text full">Un e-mail, un numéro ou les deux : au moins un des deux est obligatoire.</p></div><div class="form-foot"><button class="btn ghost" type="button" data-action="close-modal">Annuler</button><button class="btn primary" type="submit">Créer l’employé et son accès</button></div></form>`;}
 if(type==='invite'){title='Partager le lien d’activation';body=`${inviteCard(app.inviteResult)}<div class="form-foot"><button class="btn primary" type="button" data-action="close-modal">Terminer</button></div>`;}
 if(type==='submit'){const t=app.tasks.find(x=>x.id===app.modal.id);title='Soumettre le travail';body=`<p class="modal-desc">Mission : <strong>${esc(t?.title)}</strong>. L’administrateur examinera ton travail avant validation.</p><form id="submit-form"><div class="field"><label for="employee_note">Compte rendu / explication *</label><textarea id="employee_note" maxlength="3000" name="employee_note" required placeholder="Ce qui a été réalisé, les résultats, les éventuelles difficultés…">${esc(t?.employee_note||'')}</textarea></div><div class="form-foot"><button class="btn ghost" type="button" data-action="close-modal">Annuler</button><button class="btn primary" type="submit">Envoyer pour validation</button></div></form>`;}
 if(type==='reject'){const t=app.tasks.find(x=>x.id===app.modal.id);title='Demander une correction';body=`<p class="modal-desc">Mission : <strong>${esc(t?.title)}</strong>. Indique à l’employé ce qui doit être corrigé.</p><form id="reject-form"><div class="field"><label for="admin_note">Commentaire de correction *</label><textarea id="admin_note" name="admin_note" maxlength="3000" required placeholder="Explique précisément les corrections attendues…"></textarea></div><div class="form-foot"><button class="btn ghost" type="button" data-action="close-modal">Annuler</button><button class="btn danger" type="submit">Demander une correction</button></div></form>`;}
 return `<div class="modal-overlay" data-action="overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" title="Fermer">×</button></div><div class="modal-body">${body}</div></div></div>`;
}
function superView(){const d=app.superData;if(!d)return `<section class="panel" style="padding:24px"><h3>Supervision GW</h3><p>Les mesures sont récupérées depuis Cloudflare lorsque tu es connecté.</p><button class="btn primary" data-action="super-refresh">Rafraîchir</button></section>`;const n=d.stats||{};return `<div class="page-heading"><div><h2>Centre de supervision</h2><p>Propriétaire · Greatness Winner</p></div><button class="btn ghost" data-action="super-refresh">↻ Actualiser</button></div><div class="superhero"><div><strong>GW SUIVI · PROPRIÉTAIRE</strong><h2>● Application disponible</h2><p>Base Cloudflare D1 : ${esc(d.system?.database||'inconnue')} · ${esc(dateFmt(d.checked_at))}</p></div></div><div class="stats">${statCard('Responsables',n.admins||0,'Administrateurs de l’entreprise','♙')}${statCard('Employés',n.employees||0,'Collaborateurs','♟')}${statCard('Missions',n.tasks||0,'Tâches au total','☷')}${statCard('Erreurs récentes',n.errors_24h||0,'Dernières 24 heures','⚑','orange')}</div><section class="panel" style="padding:24px;margin-top:16px"><h3>Accès et maintenance</h3><p>Les indicateurs ci-dessus sont des vérifications ponctuelles, et non une surveillance externe continue.</p><div class="button-row" style="margin-top:16px"><button class="btn primary" data-action="view" data-id="admins">Gérer les administrateurs</button><button class="btn ghost" data-action="view" data-id="errors">Journal des incidents</button></div></section>`;}
function adminsView(){
 const d=app.superData;if(!d)return superView();
 const people=d.admins||[],pending=d.pendingInvites||[];
 return `<div class="page-heading"><div><h2>Responsables de l’entreprise</h2><p>Crée un accès par e-mail, WhatsApp ou les deux.</p></div></div>
 <section class="panel" style="padding:22px"><h3>Inviter un responsable</h3><p class="help-text">Une coordonnée suffit. Le lien est personnel, valable 7 jours.</p>
 <form id="super-invite-form" class="contact-form"><div class="field"><label>Nom du responsable *</label><input name="name" maxlength="100" required placeholder="Prénom et nom"></div>
 <div class="field"><label>Adresse e-mail (facultative)</label><input name="email" type="email" maxlength="250" placeholder="nom@entreprise.com"></div>
 <div class="field"><label>Numéro WhatsApp (facultatif)</label><input name="phone" type="tel" inputmode="tel" placeholder="+22890123456"></div>
 <p class="help-text full">Renseigne au moins un contact. Pour le Togo, un numéro local à 8 chiffres est accepté.</p>
 <button class="btn primary full" type="submit">Créer le lien d’activation</button></form>
 ${app.inviteResult?.role==='admin'?inviteCard(app.inviteResult):''}</section>
 <section class="panel" style="margin-top:18px;padding:22px"><h3>Responsables actifs ou enregistrés (${people.length})</h3>
 ${people.map(a=>`<div class="settings-row"><div><strong>${esc(a.name)}</strong><span>${esc(contactLabel(a))} · ${a.user_id?'Compte créé':'En attente'} · ${Number(a.active)?'Actif':'Désactivé'}</span></div><button class="btn tiny ${Number(a.active)?'danger':'ghost'}" data-action="super-toggle" data-id="${esc(a.id)}" data-active="${Number(a.active)?'0':'1'}">${Number(a.active)?'Désactiver':'Réactiver'}</button></div>`).join('')||'<p>Aucun responsable enregistré.</p>'}
 </section><section class="panel" style="margin-top:18px;padding:22px"><h3>Invitations de responsables en attente (${pending.length})</h3>
 ${pending.map(a=>`<div class="settings-row"><div><strong>${esc(a.name)}</strong><span>${esc(contactLabel(a))} · Activation en attente</span></div><button class="btn tiny ghost" data-action="reinvite-admin" data-id="${esc(a.id)}">Regénérer le lien</button></div>`).join('')||'<p>Aucune invitation en attente.</p>'}</section>`;
}
function errorsView(){const d=app.superData;if(!d)return superView();return `<div class="page-heading"><div><h2>Journal des incidents</h2><p>Événements internes enregistrés par l’application</p></div><button class="btn ghost" data-action="super-refresh">↻ Actualiser</button></div><div class="notice blue">Ces données ne remplacent pas les journaux Cloudflare pour détecter les pannes réseau ou les erreurs survenues avant l’exécution du serveur.</div><section class="panel" style="margin-top:16px;padding:22px">${d.events?.length?d.events.map(e=>`<div class="settings-row"><div><strong>${esc(e.action)}</strong><span>${esc(e.kind)} · ${esc(dateFmt(e.created_at))} ${esc(e.detail||'')}</span></div></div>`).join(''):'<p>Aucun événement enregistré pour le moment.</p>'}</section>`;}
async function superRefresh(){if(!superAdmin()||!app.online)return;try{app.superData=await api('/api/super/overview');render();}catch(e){notify('Supervision : '+e.message,true);}}
async function superInvite(fd){
 const contact=checkedContacts(fd.get('email'),fd.get('phone'));
 const data=await api('/api/super/invite',{method:'POST',body:JSON.stringify({name:String(fd.get('name')||'').trim(),...contact})});
 app.inviteResult=data;await superRefresh();notify('Lien créé. Envoie-le par le canal disponible.');
}
async function reinviteAdmin(id){
 if(!confirm('Regénérer un lien ? L’ancien lien ne sera plus valide.'))return;
 const data=await api('/api/super/reinvite',{method:'POST',body:JSON.stringify({id})});
 app.inviteResult=data;await superRefresh();notify('Nouveau lien prêt à envoyer.');
}
async function superToggle(id,active){if(!confirm(active?'Réactiver ce responsable ?':'Désactiver ce responsable et déconnecter ses sessions ?'))return;await api('/api/super/toggle',{method:'POST',body:JSON.stringify({id,active})});await superRefresh();notify('Accès mis à jour.');}
function authHTML(){
 const signup=app.authView==='signup',inv=app.invitePreview;
 const hasLink=Boolean(app.inviteToken);
 const intro=signup?(hasLink?'Ton invitation GW Suivi : définis un mot de passe pour activer ton compte.':'Le propriétaire utilise son code privé. Les autres membres reçoivent un lien d’activation.'):'Connecte-toi avec ton e-mail ou ton numéro de téléphone.';
 return `<div class="auth-page"><div class="auth-art"><div class="brand"><div class="brand-icon">GW</div><div class="brand-copy"><strong>GW Suivi</strong><span>Greatness Winner</span></div></div><div><h1>Grandir ensemble.<br>Chaque mission compte.</h1><p>Un espace simple pour suivre les tâches, respecter les délais et récompenser les efforts.</p></div><div style="color:#a7bbd1;font-size:12px">Gestion des employés • Primes • Offline-first</div></div><div class="auth-form-wrap"><div class="auth-form"><div class="auth-tabs"><button data-action="auth-tab" data-id="login" class="${!signup?'active':''}">Connexion</button><button data-action="auth-tab" data-id="signup" class="${signup?'active':''}">Créer mon accès</button></div><h2>${signup?'Créer mon compte':'Bienvenue 👋'}</h2><p>${intro}</p>${app.authError?`<div class="notice">${esc(app.authError)}</div>`:''}
 ${hasLink&&inv?`<div class="notice blue"><strong>Invitation : ${esc(inv.name)} (${esc(inv.role==='admin'?'Responsable':'Employé')})</strong><p>${esc(contactLabel(inv))}</p></div>`:''}
 <form id="auth-form">${!signup?`<div class="field"><label for="auth_identifier">E-mail ou numéro de téléphone</label><input id="auth_identifier" name="identifier" autocomplete="username" required placeholder="adresse@mail.com ou +22890123456" /></div>`:
 hasLink&&inv?`<div class="field"><label>E-mail ou WhatsApp du compte invité</label><input value="${esc(contactLabel(inv))}" readonly /></div>`:
 `<div class="field"><label for="auth_email">E-mail (facultatif)</label><input id="auth_email" name="email" type="email" autocomplete="email" placeholder="toi@entreprise.com" /></div><div class="field"><label for="auth_phone">WhatsApp (facultatif)</label><input id="auth_phone" name="phone" type="tel" autocomplete="tel" placeholder="+22890123456" /></div>`}
 <div class="field"><label for="auth_password">Mot de passe</label><input id="auth_password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" minlength="12" required placeholder="12 caractères minimum" /></div>
 ${signup&&!hasLink?'<div class="field"><label for="bootstrap_code">Code d’activation du Super administrateur</label><input id="bootstrap_code" name="bootstrapCode" autocomplete="off" placeholder="Réservé au propriétaire" /></div><div class="field"><label for="admin_invite_code">Ancien code responsable (si reçu)</label><input id="admin_invite_code" name="adminInviteCode" autocomplete="off" placeholder="Facultatif" /></div><div class="field"><label for="invite_code">Ancien code employé (si reçu)</label><input id="invite_code" name="inviteCode" autocomplete="off" placeholder="Facultatif" /></div>':''}
 <button class="btn primary" type="submit">${signup?'Activer mon compte':'Se connecter'}</button></form><p style="margin-top:20px;font-size:11px">Après une première connexion, tes tâches restent consultables hors ligne sur cet appareil.</p></div></div></div>`;
}
function render(){if(!app.ready)return;const outlet=CLOUD && !app.session?authHTML():shell((({dashboard,tasks:tasksView,employees:employeesView,settings:settingsView,super:superView,admins:adminsView,errors:errorsView})[app.view]||(superAdmin()?superView:dashboard))());ROOT.innerHTML=outlet;}

/* Action locale d'abord, puis synchronisation serveur différée. */
async function localAction(op){if(CLOUD)app.queue.push({...op,operation_id:uuid()});await save();render();if(CLOUD && app.online)sync().catch(e=>notify(e.message,true));}
async function createTask(fd){if(!admin())return;const due=new Date(fd.get('due_at')),before=new Date(fd.get('bonus_before')||fd.get('due_at'));const amount=Number(fd.get('bonus_amount')||0);if(!fd.get('employee_id')||!fd.get('title')||Number.isNaN(due.getTime())||Number.isNaN(before.getTime()))throw new Error('Complète les champs obligatoires.');if(before>due)throw new Error('La date de prime doit être avant ou égale à l’échéance de la tâche.');if(amount<0)throw new Error('La prime ne peut pas être négative.');const old=app.modal.task;
 const t={id:old?.id||uuid(),title:String(fd.get('title')).trim(),description:String(fd.get('description')||'').trim(),employee_id:String(fd.get('employee_id')),due_at:due.toISOString(),priority:String(fd.get('priority')||'normal'),bonus_amount:amount,bonus_before:before.toISOString(),status:old?.status||'todo',submitted_at:old?.submitted_at||null,approved_at:old?.approved_at||null,bonus_awarded:old?.bonus_awarded||0,bonus_override:old?.bonus_override||false,client_submitted_at:old?.client_submitted_at||null,employee_note:old?.employee_note||'',admin_note:old?.admin_note||'',updated_at:iso(),created_at:old?.created_at||iso()};if(old && old.employee_id!==t.employee_id){t.status='todo';t.submitted_at=null;t.approved_at=null;t.bonus_awarded=0;t.bonus_override=false;t.client_submitted_at=null;t.employee_note='';t.admin_note='';}if(old){app.tasks=app.tasks.map(x=>x.id===old.id?t:x);}else app.tasks.push(t);
 app.modal=null;await localAction({type:old?'task_patch':'task_upsert',task:t});notify(old?'Tâche modifiée.':'Mission attribuée.');}
async function createPerson(fd){
 if(!admin())return;
 const name=String(fd.get('person_name')||'').trim(),contact=checkedContacts(fd.get('person_email'),fd.get('person_phone'));
 if(!name)throw new Error('Le nom est obligatoire.');
 if(app.people.some(p=>contact.email&&p.email===contact.email||contact.phone&&p.phone===contact.phone))throw new Error('Ce contact existe déjà.');
 const p={id:uuid(),name,...contact,role:'employee',active:true,user_id:null,created_at:iso(),updated_at:iso()};
 if(!CLOUD){app.people.push(p);app.modal=null;await localAction({type:'person_upsert',person:p});notify('Employé créé dans la démonstration.');return;}
 if(!app.online)throw new Error('Une connexion Internet est requise pour générer le lien personnel.');
 const result=await api('/api/ops',{method:'POST',body:JSON.stringify({op:{type:'person_upsert',person:p}})});
 app.inviteResult=result;app.modal={type:'invite'};
 await sync();render();notify('Employé créé. Choisis WhatsApp ou e-mail pour transmettre son accès.');
}
async function reinviteEmployee(id){
 if(!app.online)throw new Error('Internet requis.');
 if(!confirm('Générer un nouveau lien ? L’ancien lien sera désactivé.'))return;
 app.inviteResult=await api('/api/people/reinvite',{method:'POST',body:JSON.stringify({id})});
 app.modal={type:'invite'};render();
}
async function updateTask(id,patch,type){const old=app.tasks.find(t=>t.id===id);if(!old)return;const upd={...old,...patch,updated_at:iso()};app.tasks=app.tasks.map(t=>t.id===id?upd:t);await localAction({type,id,...(type==='task_patch'?{patch:patch}:{note:patch.employee_note})});}
async function startTask(id){const t=app.tasks.find(t=>t.id===id);if(!t||t.employee_id!==app.meId||!['todo','changes_requested'].includes(t.status))return;await updateTask(id,{status:'in_progress'},'start_task');notify('Mission commencée.');}
async function approveTask(id){if(!admin())return;const t=app.tasks.find(t=>t.id===id);if(!t||t.status!=='submitted')return;let bonusOverride=false;if(CLOUD&&Number(t.bonus_amount)>0&&t.client_submitted_at&&t.bonus_before&&new Date(t.submitted_at)>new Date(t.bonus_before)&&new Date(t.client_submitted_at)<=new Date(t.bonus_before)){bonusOverride=confirm('Soumission enregistrée hors ligne avant l’échéance, mais synchronisée après. Accorder exceptionnellement la prime de '+money(t.bonus_amount)+' ?');}const earned=(isEligible(t)||bonusOverride)?Number(t.bonus_amount||0):0;await updateTask(id,{status:'approved',approved_at:iso(),bonus_awarded:earned,bonus_override:bonusOverride,admin_note:''},'task_patch');notify(earned?`Travail validé. Prime : ${money(earned)}.`:'Travail validé sans prime.');}
async function submitTask(id,note){const t=app.tasks.find(t=>t.id===id);if(!t||t.employee_id!==app.meId||!['todo','in_progress','changes_requested'].includes(t.status))return;const submittedAt=iso();const upd={...t,status:'submitted',submitted_at:submittedAt,client_submitted_at:submittedAt,employee_note:note,updated_at:submittedAt};app.tasks=app.tasks.map(x=>x.id===id?upd:x);app.modal=null;await localAction({type:'submit_task',id,note,clientTime:submittedAt});notify('Travail soumis pour validation.');}
async function rejectTask(id,note){if(!admin())return;await updateTask(id,{status:'changes_requested',admin_note:note,approved_at:null,bonus_awarded:0},'task_patch');app.modal=null;notify('Correction demandée.');}
function exportData(){const pack={app:'GW Suivi',version:1,exported_at:iso(),people:app.people,tasks:app.tasks};const blob=new Blob([JSON.stringify(pack,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`GW-Suivi-sauvegarde-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function importData(file){if(CLOUD)throw new Error('Import disponible uniquement en démonstration.');if(file.size>5_000_000)throw new Error('Fichier trop volumineux.');const data=JSON.parse(await file.text());if(data.app!=='GW Suivi'||!Array.isArray(data.people)||!Array.isArray(data.tasks))throw new Error('Fichier de sauvegarde GW Suivi invalide.');if(!data.people.some(x=>x.role==='admin'))throw new Error('Sauvegarde sans administrateur.');app.people=data.people;app.tasks=data.tasks;app.meId=data.people.find(x=>x.role==='admin').id;app.queue=[];app.view='dashboard';await persistAndRender();notify('Sauvegarde restaurée.');}

/* API Cloudflare Worker + D1. Auth et autorisations vérifiées côté serveur. */
function getSession(){try{return JSON.parse(localStorage.getItem(LS_SESSION)||'null')}catch{return null}}
function setSession(session){app.session=session;if(session)localStorage.setItem(LS_SESSION,JSON.stringify(session));else localStorage.removeItem(LS_SESSION)}
async function api(path,options={},auth=true){if(!app.online)throw new Error('Aucune connexion Internet.');const headers={'Content-Type':'application/json',...(auth&&app.session?{Authorization:`Bearer ${app.session.access_token}`}:{})};let response;try{response=await fetch(path,{...options,headers});}catch{throw new Error('Connexion au serveur impossible.')}const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Erreur réseau ${response.status}`);return data;}
async function refreshAuth(){if(!app.session)return false;if(!app.online)return true;if(Number(app.session.expires_at)>Date.now()/1000)return true;app.authError='Session expirée. Connecte-toi de nouveau.';setSession(null);render();throw new Error(app.authError);}
async function authRequest(identifier,password,signup,bootstrapCode='',inviteCode='',adminInviteCode='',email='',phone=''){
 if(!app.online)throw new Error('Connexion nécessaire pour accéder à un compte.');
 const path=signup?'/api/auth/signup':'/api/auth/login';
 const body=signup?{email,phone,password,bootstrapCode,inviteCode,adminInviteCode,inviteToken:app.inviteToken||''}:{identifier,password};
 const response=await api(path,{method:'POST',body:JSON.stringify(body)},false);
 if(signup){app.inviteToken='';app.invitePreview=null;app.authView='login';app.authError='Compte activé. Connecte-toi avec ton e-mail ou ton numéro.';render();return;}
 setSession(response);restore(await storageGet(storageKey()));app.authError='';app.view='dashboard';render();await sync();
}
async function replay(op){return await api('/api/ops',{method:'POST',body:JSON.stringify({op})});}
async function sync(){if(!CLOUD||!app.session||!app.online||app.syncing)return;app.syncing=true;render();try{await refreshAuth();let tries=0;while(app.queue.length){const op=app.queue[0];await replay(op);app.queue.shift();await save();if(++tries>500)break;}const result=await api('/api/snapshot');const activeMe=result.people.find(p=>p.user_id===app.session.user.id && p.active);if(!activeMe)throw new Error('Compte non associé à un employé actif.');app.people=result.people;app.tasks=result.tasks;app.meId=activeMe.id;if(activeMe.role==='superadmin'){if(!['super','admins','errors','settings'].includes(app.view))app.view='super';}else if(['super','admins','errors'].includes(app.view)){app.view='dashboard';app.superData=null;}app.lastSync=iso();await save();app.authError='';if(activeMe.role==='superadmin'&&!app.superData)await superRefresh();}catch(e){notify(`${app.queue.length?'Synchronisation en attente':'Connexion serveur'} : ${e.message}`,true);}finally{app.syncing=false;render();}}
async function signOut(){if(app.queue.length&&!confirm('Des modifications ne sont pas synchronisées. Se déconnecter effacera les modifications locales. Continuer ?'))return;const key=storageKey();if(app.online){try{await api('/api/auth/logout',{method:'POST'});}catch{}}await storageDelete(key);setSession(null);app.people=[];app.tasks=[];app.queue=[];app.meId=null;app.authError='';app.view='dashboard';render();}

/* Délégation d'événements : fonctionne après tout rerender. */
document.addEventListener('click',async event=>{const node=event.target.closest('[data-action]');if(!node)return;const action=node.dataset.action,id=node.dataset.id;if(action==='overlay'&&event.target!==node)return;try{switch(action){case 'view':setView(id);break;case 'tab':app.tab=id;render();break;case 'new-task':if(admin()){app.modal={type:'task'};render();}break;case 'edit-task':if(admin()){app.modal={type:'task',task:app.tasks.find(t=>t.id===id)};render();}break;case 'assign':app.modal={type:'task',employeeId:id};render();break;case 'new-person':app.inviteResult=null;app.modal={type:'person'};render();break;case 'close-modal':case 'overlay':app.modal=null;render();break;case 'submit':app.modal={type:'submit',id};render();break;case 'reject':app.modal={type:'reject',id};render();break;case 'start':await startTask(id);break;case 'approve':await approveTask(id);break;case 'sync':if(!CLOUD){notify('Les données du mode démo sont déjà enregistrées localement.');break;}if(!app.online){notify('Aucune connexion Internet. Données locales disponibles.');break;}await sync();break;case 'export':exportData();break;case 'import':$('#import-file')?.click();break;case 'install':if(window.gwInstallPrompt){window.gwInstallPrompt.prompt();await window.gwInstallPrompt.userChoice;window.gwInstallPrompt=null;}else notify('Dans Chrome : menu ⋮ → Ajouter à l’écran d’accueil / Installer l’application.');break;case 'auth-tab':app.authView=id;app.authError='';render();break;case 'super-refresh':await superRefresh();break;case 'super-toggle':await superToggle(id,node.dataset.active==='1');break;case 'reinvite-admin':await reinviteAdmin(id);break;case 'reinvite-employee':await reinviteEmployee(id);break;case 'share-whatsapp':shareInvite('whatsapp');break;case 'share-email':shareInvite('email');break;case 'share-copy':shareInvite('copy');break;case 'super-copy':if(app.inviteCode){await navigator.clipboard.writeText(app.inviteCode.code);notify('Code copié.');}break;case 'logout':await signOut();break;}}catch(e){notify(e.message||'Une erreur est survenue.',true);}});
document.addEventListener('submit',async event=>{const form=event.target;if(!['task-form','person-form','submit-form','reject-form','auth-form','super-invite-form'].includes(form.id))return;event.preventDefault();const fd=new FormData(form);const btn=$('button[type="submit"]',form);if(btn)btn.disabled=true;try{if(form.id==='task-form')await createTask(fd);if(form.id==='person-form')await createPerson(fd);if(form.id==='submit-form'){const note=String(fd.get('employee_note')||'').trim();if(!note)throw new Error('Le compte rendu est obligatoire.');await submitTask(app.modal.id,note);}if(form.id==='reject-form'){const note=String(fd.get('admin_note')||'').trim();if(!note)throw new Error('Indique la correction attendue.');await rejectTask(app.modal.id,note);}if(form.id==='super-invite-form')await superInvite(fd);if(form.id==='auth-form')await authRequest(String(fd.get('identifier')||'').trim(),String(fd.get('password')),app.authView==='signup',String(fd.get('bootstrapCode')||''),String(fd.get('inviteCode')||''),String(fd.get('adminInviteCode')||''),String(fd.get('email')||''),String(fd.get('phone')||''));}catch(e){notify(e.message||'Erreur de formulaire',true);if(form.id==='auth-form'){app.authError=e.message;render();}}finally{if(btn&&btn.isConnected)btn.disabled=false;}});
document.addEventListener('input',event=>{if(event.target.id==='search-tasks'){app.query=event.target.value;const pos=event.target.selectionStart;render();const elem=$('#search-tasks');elem?.focus();try{elem?.setSelectionRange(pos,pos)}catch{}}});
document.addEventListener('change',async event=>{if(event.target.id==='demo-role'&&!CLOUD){app.meId=event.target.value;app.view='dashboard';await persistAndRender();notify(`Profil actif : ${me()?.name}`);}if(event.target.id==='import-file'&&event.target.files?.[0]){try{await importData(event.target.files[0]);}catch(e){notify(e.message,true);}}});
window.addEventListener('online',()=>{app.online=true;render();if(CLOUD)sync()});window.addEventListener('offline',()=>{app.online=false;render()});window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();window.gwInstallPrompt=event;});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&CLOUD&&app.online)sync()});
async function boot(){if(CLOUD){
 const token=new URLSearchParams(location.hash.slice(1)).get('invite');
 if(token){history.replaceState(null,'',location.pathname+location.search);app.inviteToken=token;app.authView='signup';try{app.invitePreview=await api('/api/auth/invite/preview',{method:'POST',body:JSON.stringify({token})},false);}catch(e){app.authError=e.message;}}
setSession(getSession());if(app.session){restore(await storageGet(storageKey()));}if(app.session&&app.online){try{await refreshAuth()}catch{}}}else{const snapshot=await storageGet('demo');if(snapshot)restore(snapshot);else{seed();await save();}}app.ready=true;render();if(CLOUD&&app.session&&app.online)sync();if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));}}
boot().catch(e=>{ROOT.innerHTML=`<div class="boot-screen"><div class="brand-icon">GW</div><p>Impossible d'ouvrir l'application : ${esc(e.message)}</p></div>`;});